import os
import requests

response = requests.post(
    "https://api.typesafe.ai/v1/systemone",
    headers={"Authorization": f"Bearer {os.environ['TYPESAFE_API_KEY']}"},
    json={
        "model": "jev-latest",
        "state": "Le client a été facturé deux fois et demande un remboursement.",
        "questions": {
            "departement": {
                "type": "choice",
                "instructions": "Quel service doit traiter ce message ?",
                "criteria": {
                    "facturation": "Factures, paiements et remboursements",
                    "technique": "Bugs et pannes",
                    "autre": "Tout le reste",
                },
            },
            "risque_depart": {
                "type": "noul",
                "instructions": "Le client menace-t-il de partir ?",
            },
        },
    },
    timeout=30,
)
response.raise_for_status()
answers = response.json()["answers"]
print(answers["departement"]["choice"])
print(answers["departement"]["probabilities"])
print(answers["risque_depart"]["noul"])

type Answer =
  | { type: "noul"; noul: number }
  | { type: "choice"; choice: string; confidence: number; probabilities: Record<string, number> }
  | { type: "score"; score: number; confidence: number; probabilities: Record<string, number> };

type DecisionResponse = {
  model: string;
  answers: Record<string, Answer>;
};

async function decide(state: string, questions: Record<string, unknown>): Promise<DecisionResponse> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const response = await fetch("https://api.typesafe.ai/v1/systemone", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${process.env.TYPESAFE_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ model: "jev-latest", state, questions }),
      signal: controller.signal,
    });
    if (!response.ok) throw new Error(`Decision HTTP ${response.status}`);
    return (await response.json()) as DecisionResponse;
  } finally {
    clearTimeout(timer);
  }
}

const result = await decide("Le client demande un remboursement.", {
  urgence: {
    type: "score",
    instructions: "Quelle est l'urgence de cette demande ?",
    criteria: ["peut attendre", "cette semaine", "aujourd'hui"],
  },
});

const answer = result.answers.urgence;
if (answer?.type === "score" && answer.score >= 1.5) {
  console.log("escalade", answer.confidence);
